def _keep(probs, indexes):
    """Zero every probability whose index is not in `indexes`, then renormalise."""
    kept = [p if i in indexes else 0.0 for i, p in enumerate(probs)]
    total = sum(kept)
    return [p / total for p in kept]


def filter_probs(probs, top_k=None, top_p=None):
    if top_k is not None and top_k < 1:
        raise ValueError("top_k must be at least 1")
    if top_p is not None and not 0 < top_p <= 1:
        raise ValueError("top_p must be in (0, 1]")
    result = list(probs)
    if top_k is not None:
        order = sorted(range(len(result)), key=lambda i: (-result[i], i))
        result = _keep(result, set(order[:top_k]))
    if top_p is not None:
        order = sorted(range(len(result)), key=lambda i: (-result[i], i))
        total, keep = 0.0, set()
        for i in order:
            keep.add(i)
            total += result[i]
            if total >= top_p:
                break
        result = _keep(result, keep)
    return result
